// Deliberately bounded sample replies: these are not generated by an LLM.
export function demoReply(message, context = '') {
 const text = message.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
 if(context && /i’d like to explore|i'd like to explore|vorrei esplorare|je voudrais explorer|me gustaria explorar|gostaria de explorar/.test(text))
   return "Prenons l’exemple "+context+" comme point de départ, pas comme conclusion. Commençons par comprendre la décision que votre équipe prend aujourd’hui, les informations disponibles et la valeur d’un meilleur résultat. Quelle partie correspond le mieux à votre situation ? Cet aperçu peut cadrer la conversation, mais pas encore analyser votre entreprise.";
 if (/^(hi|hey|hello|good morning|good afternoon|ciao|salve|buongiorno|bonjour|salut|bonsoir|hola|buenos dias|buenas tardes|ola|oi|bom dia|boa tarde)\b/.test(text) || /how are you|come stai|comment allez|como estas|como vai/.test(text))
   return "Bonjour, ravi de faire votre connaissance. Je suis ici pour explorer avec vous ce que Heading South pourrait apporter à votre entreprise. Il s’agit pour l’instant d’une démonstration guidée. Qu’est-ce qui vous amène aujourd’hui ?";
 if (/cost|price|pricing|budget|fee|prezz|prix|tarif|precio|preco|orcamento/.test(text))
   return "Je n’ai pas de tarif publié à vous communiquer. Le périmètre dépend de la décision, des systèmes concernés et de l’accompagnement nécessaire. Un point de départ utile est le coût de laisser le problème sans solution. Qu’est-ce qui prend le plus de temps ou freine les progrès ?";
 if (/drone|agri|farm|crop|food|geospatial|agro|campo|lavoura|geospaz|geoespa/.test(text) && !/export|trade|customs|international|esport|dogan|douan|aduan|alfand|internaz|commercio|commerce|comercio/.test(text))
   return "L’agroalimentaire et l’AgriTech sont notre premier domaine d’action. Les points de départ possibles incluent les données de drones et géospatiales, les opérations de précision et la visibilité sur la chaîne d’approvisionnement. La question utile est de savoir quelle décision changerait avec de meilleures informations. Pensez-vous au terrain ou à l’entreprise dans son ensemble ?";
 if (/export|trade|customs|international|esport|dogan|douan|aduan|alfand|internaz|commercio|commerce|comercio/.test(text))
   return "Pour l’export et le commerce, nous commencerions là où l’information ou les tâches répétées ralentissent une décision : intelligence de marché, conformité ou priorités commerciales. La revue humaine reste essentielle pour les décisions réglementaires. Où se situent les frictions aujourd’hui ?";
 if (/financ|finanz|invest|invers|diligence|capital/.test(text))
   return "Pour les équipes d’investissement, l’enjeu est de disposer de meilleures preuves : due diligence, visibilité du portefeuille et justification de la technologie. L’IA peut organiser l’information, mais ne doit pas remplacer un jugement responsable. Évaluez-vous une opportunité ou améliorez-vous une entreprise existante ?";
 if (/sell|sales|customer|grow|commercial|comercial|client|vend|cresc|croiss|crecim/.test(text))
   return "Un point de départ utile est de comprendre où la connaissance client se perd entre le marché et votre équipe. Cela peut révéler des opportunités dans les offres, les priorités ou l’accompagnement des ventes. Quelle partie du parcours client souhaitez-vous améliorer en priorité ?";
 if (/operation|operaz|operac|supply|inventory|automat|workflow|logist|supriment|suministr|approvision|flusso/.test(text))
   return "Commencez par un processus récurrent. Identifiez qui le réalise, les informations nécessaires et les pertes de temps. Vous pourrez alors décider s’il faut automatiser, améliorer la visibilité ou simplement clarifier le processus. Quel processus vous vient à l’esprit ?";
 if (/how.*work|approach|start|help|sector|come.*lavor|comment.*travaill|como.*trab|como.*trabalh|approccio|approche|enfoque|abordagem|settore|secteur|setor|aiut|aide|ayud|ajud/.test(text))
   return "Nous partons du problème métier, identifions où créer de la valeur, puis choisissons la bonne réponse : construire, acheter, intégrer ou ne rien faire. L’adoption et la mesure font partie du plan dès le premier jour. À quoi ressemblerait un meilleur résultat pour votre équipe ?";
 if (/thank|grazie|merci|gracias|obrigad/.test(text)) return "Avec plaisir. Vous pouvez explorer les expertises et les secteurs du site, ou revenir ici avec une autre question.";
 return "Cet aperçu utilise un nombre limité de réponses guidées : je ne peux donc pas encore analyser chaque détail de votre situation. Le conseiller en direct nécessitera une connexion IA et une base de connaissances vérifiée. Pour l’instant, nous pouvons explorer l’approche, les secteurs, l’automatisation, la croissance ou l’investissement.";
}
